class InternalRuleType(str, Enum):
    CHAR = "CHAR"
    CHAR_RNG_UPPER = "CHAR_RNG_UPPER"
    RULE_REF = "RULE_REF"
    ALT = "ALT"
    END = "END"

    CHAR_NOT = "CHAR_NOT"
    CHAR_ALT = "CHAR_ALT"

    def __str__(self) -> str:
        return self.value


@dataclass
class InternalRuleDefChar:
    value: List[int]
    type: InternalRuleType = field(default=InternalRuleType.CHAR, init=False)


